"""
test_pipeline.py

Covers the three bug classes that reached production this season. Each one
produced plausible numbers and threw no exception, which is why they survived
for weeks and were caught by eye rather than by anything automated.

Run with:
    python -m pytest test_pipeline.py -v
or without pytest installed:
    python test_pipeline.py
"""

import importlib.util
import json
import sys
from pathlib import Path

RACES = Path("races")

# Race folders from this one onward were generated by the current API pipeline.
# Earlier files were written by hand or by the FastF1 version and carry known
# gaps that are not regenerated, because their predictions are published.
PIPELINE_FROM = "10_belgium"


def _load(path):
    spec = importlib.util.spec_from_file_location("race_data", path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def _fetcher():
    sys.argv = ["fetch_race_data.py"]
    spec = importlib.util.spec_from_file_location("fetch", "fetch_race_data.py")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def race_folders():
    return sorted(d for d in RACES.iterdir() if d.is_dir() and d.name[0].isdigit())


# ---------------------------------------------------------------------------
# Bug 1: grid penalties were applied by hand and could be misread.
# The Hungary grid is a known-good fixture: Hamilton and Antonelli each took a
# three-place drop and Perez started from the pit lane. The FIA applied
# Antonelli's penalty first, then Hamilton's.
# ---------------------------------------------------------------------------

def test_penalty_reordering_matches_published_grid():
    f = _fetcher()
    qualifying = [
        "Lando Norris", "Lewis Hamilton", "Charles Leclerc",
        "Andrea Kimi Antonelli", "Oscar Piastri", "Max Verstappen",
        "George Russell", "Isack Hadjar", "Arvid Lindblad", "Nico Hulkenberg",
        "Liam Lawson", "Pierre Gasly", "Franco Colapinto", "Gabriel Bortoleto",
        "Esteban Ocon", "Fernando Alonso", "Ollie Bearman", "Carlos Sainz",
        "Alex Albon", "Lance Stroll", "Valtteri Bottas", "Sergio Perez",
    ]
    grid = [{"driver": n, "team": "x", "pos": i + 1, "q_time": 80.0 + i}
            for i, n in enumerate(qualifying)]

    out = f.apply_penalties(
        grid,
        {"Lewis Hamilton": 3, "Andrea Kimi Antonelli": 3},
        ["Sergio Perez"],
    )
    got = [d["driver"] for d in sorted(out, key=lambda x: x["pos"])]

    expected_top = [
        "Lando Norris", "Charles Leclerc", "Oscar Piastri", "Max Verstappen",
        "Lewis Hamilton", "George Russell", "Andrea Kimi Antonelli",
        "Isack Hadjar",
    ]
    assert got[:8] == expected_top, f"grid order wrong: {got[:8]}"
    assert got[-1] == "Sergio Perez", "pit lane starter is not last"
    assert len(got) == len(qualifying), "drivers lost or duplicated"
    assert len(set(got)) == len(got), "duplicate driver on the grid"


def test_penalty_overflow_keeps_every_driver():
    """Baku R15. A penalty applies to the qualifying position, so a drop can
    aim at a slot that does not exist. Perez qualified 20th and took three
    places, targeting 23rd, with both Aston Martins already in the pit lane.
    The old rebuild capped targets at the grid size, so 23 fell outside the
    fill loop and Perez was written out of the grid with no warning: 21 cars
    returned where 22 went in, and the engine ran on 21.
    """
    f = _fetcher()
    qualifying = [
        "George Russell", "Charles Leclerc", "Oscar Piastri", "Isack Hadjar",
        "Max Verstappen", "Lando Norris", "Lewis Hamilton", "Pierre Gasly",
        "Liam Lawson", "Nico Hulkenberg", "Arvid Lindblad", "Esteban Ocon",
        "Franco Colapinto", "Gabriel Bortoleto", "Ollie Bearman",
        "Andrea Kimi Antonelli", "Alex Albon", "Valtteri Bottas",
        "Carlos Sainz", "Sergio Perez", "Fernando Alonso", "Lance Stroll",
    ]
    grid = [{"driver": n, "team": "x", "pos": i + 1, "q_time": 100.0 + i}
            for i, n in enumerate(qualifying)]

    out = f.apply_penalties(
        grid,
        {"Carlos Sainz": 5, "Sergio Perez": 3},
        ["Fernando Alonso", "Lance Stroll"],
    )
    got = [d["driver"] for d in sorted(out, key=lambda x: x["pos"])]

    assert len(got) == 22, f"grid lost drivers: {len(got)} of 22"
    assert set(got) == set(qualifying), "grid membership changed"
    assert len(set(got)) == len(got), "duplicate driver on the grid"
    assert [d["pos"] for d in sorted(out, key=lambda x: x["pos"])] == list(range(1, 23))

    # Twenty slots sit ahead of the two pit lane starters. Sainz aimed at 24th
    # from 19th and Perez at 23rd from 20th, so both overshoot and both fall to
    # the back of the runners, in qualifying order between themselves.
    assert got[-4:] == [
        "Carlos Sainz", "Sergio Perez", "Fernando Alonso", "Lance Stroll",
    ], f"overflow placed wrong: {got[-4:]}"

    # Every driver who was not penalised keeps their qualifying order and moves up.
    assert got[:18] == qualifying[:18], "clean runners reordered"


def test_penalty_on_unknown_driver_fails_loudly():
    """A typo in a driver name must stop the run, not silently do nothing."""
    f = _fetcher()
    grid = [{"driver": "Lando Norris", "team": "McLaren", "pos": 1, "q_time": 80.0}]
    try:
        f.apply_penalties(grid, {"Lando Noris": 3}, [])
    except SystemExit:
        return
    raise AssertionError("a misspelled driver name was accepted silently")


# ---------------------------------------------------------------------------
# Bug 2: FastF1 and the timing API spell three drivers differently. The engine
# looks FP1 up by grid name, so an unreconciled key drops that driver to the
# practice_pace fallback of 0.3 with no error. At Zandvoort this scored the
# fastest driver in the session as if he had been slowest.
# ---------------------------------------------------------------------------

def test_name_reconciliation_maps_known_variants():
    f = _fetcher()
    grid = ["Andrea Kimi Antonelli", "Ollie Bearman", "Alex Albon", "Lando Norris"]
    cases = {
        "Kimi Antonelli": "Andrea Kimi Antonelli",
        "Oliver Bearman": "Ollie Bearman",
        "Alexander Albon": "Alex Albon",
        "Lando Norris": "Lando Norris",
    }
    for raw, want in cases.items():
        assert f.reconcile_name(raw, grid) == want, f"{raw} did not map to {want}"


def test_name_reconciliation_rejects_non_starters():
    """Reserve drivers run FP1 but are not on the grid. They must not match."""
    f = _fetcher()
    grid = ["Lando Norris", "Max Verstappen"]
    assert f.reconcile_name("Colton Herta", grid) is None


def test_no_grid_driver_is_shadowed_by_a_name_variant():
    """The Zandvoort bug, encoded.

    Reserve drivers run FP1 and legitimately appear in FP1_TIMES without being
    on the grid, so a stray key is not itself a fault. The fault is a stray key
    whose surname matches a grid driver who has no FP1 time of their own: that
    is the same person under a different spelling, and the engine will score
    them on the 0.3 fallback instead of their real lap.
    """
    problems = []
    for d in race_folders():
        mod = _load(d / "data.py")
        fp1 = getattr(mod, "FP1_TIMES", {})
        if not fp1:
            continue
        names = [g["driver"] for g in mod.GRID]
        uncovered = {n.split()[-1].lower(): n for n in names if n not in fp1}
        for key in fp1:
            surname = key.split()[-1].lower()
            if key not in names and surname in uncovered:
                problems.append(
                    f"{d.name}: FP1 has '{key}' while grid driver "
                    f"'{uncovered[surname]}' has no time")
    assert not problems, "name variants shadowing grid drivers:\n  " + "\n  ".join(problems)


# ---------------------------------------------------------------------------
# Bug 3: results were hand-entered for nine races and the midfield was up to
# 16 places out, which corrupted the XGBoost labels. A schema check would not
# have caught wrong values, but it does catch the structural faults that came
# with them.
# ---------------------------------------------------------------------------

def test_race_files_are_structurally_sound():
    problems = []
    for d in race_folders():
        mod = _load(d / "data.py")
        grid = mod.GRID
        names = [g["driver"] for g in grid]
        positions = sorted(g["pos"] for g in grid)

        if positions != list(range(1, len(grid) + 1)):
            problems.append(f"{d.name}: grid positions are not 1..{len(grid)}")
        if len(set(names)) != len(names):
            problems.append(f"{d.name}: duplicate driver in GRID")

        teams = {g["team"] for g in grid}
        missing = teams - set(mod.TEAM_PACE_DEFICIT)
        if missing:
            problems.append(f"{d.name}: no pace deficit for {sorted(missing)}")

        for name in names:
            if name not in mod.DRIVER_EXPERIENCE:
                problems.append(f"{d.name}: {name} missing from DRIVER_EXPERIENCE")

        # r1_finish is legitimately absent for round 1. It is also missing in
        # several 2026 files written before the API pipeline existed; those
        # predictions are published and are not regenerated, so the check
        # applies to anything the current pipeline produces.
        if d.name >= PIPELINE_FROM:
            for name, info in mod.DRIVER_EXPERIENCE.items():
                if info.get("r1_finish") is None:
                    problems.append(f"{d.name}: {name} has r1_finish None")

        for s in getattr(mod, "SPRINT_RESULT", []):
            if s["driver"] not in names:
                problems.append(f"{d.name}: sprint name {s['driver']} not on grid")

    assert not problems, "structural problems:\n  " + "\n  ".join(problems)


def test_results_match_grid_names():
    """Every classified driver must match a grid name.

    XGBoost skips any driver it cannot match between data.py and result.json,
    so a spelling drift silently shrinks the training set instead of erroring.
    """
    problems = []
    for d in race_folders():
        rj = d / "result.json"
        if not rj.exists():
            continue
        mod = _load(d / "data.py")
        names = {g["driver"] for g in mod.GRID}
        result = json.loads(rj.read_text())["result"]
        unmatched = [r["driver"] for r in result if r["driver"] not in names]
        if unmatched:
            problems.append(f"{d.name}: {unmatched}")
    assert not problems, "result names not on the grid:\n  " + "\n  ".join(problems)


def test_fastest_lap_is_the_fastest_not_the_latest():
    """best_lap must take the quickest lap across Q1-Q3.

    Taking the latest session reached looks right until a driver's later lap is
    slower, which happens after a red flag, traffic or an aborted lap. Albon at
    Madrid set 1:35.307 in Q1 and 1:35.532 in Q2.
    """
    f = _fetcher()
    assert f.best_lap({"Q1": "1:35.307", "Q2": "1:35.532", "Q3": ""}) == 95.307
    assert f.best_lap({"Q1": "1:33.469", "Q2": "1:32.873", "Q3": "1:31.824"}) == 91.824
    assert f.best_lap({"Q1": "", "Q2": "", "Q3": ""}) is None


def test_predictions_are_never_regenerated():
    """Each prediction must match the grid it was made against.

    The project's claim is that predictions are committed before the race and
    never edited. If a prediction lists a driver who is not on that race's
    grid, something was rerun after the fact.
    """
    problems = []
    for d in race_folders():
        pj = d / "prediction.json"
        if not pj.exists():
            continue
        mod = _load(d / "data.py")
        names = {g["driver"] for g in mod.GRID}
        pred = json.loads(pj.read_text())
        # Predictions keep whatever spelling they were published with. The
        # grid files were later normalised to the API's spellings and the
        # predictions deliberately were not regenerated, so compare through
        # the same map rather than demanding an exact string match.
        variants = {
            "Kimi Antonelli": "Andrea Kimi Antonelli",
            "Oliver Bearman": "Ollie Bearman",
            "Alexander Albon": "Alex Albon",
        }
        stray = [p["driver"] for p in pred["predictions"]
                 if variants.get(p["driver"], p["driver"]) not in names]
        if stray:
            problems.append(f"{d.name}: {stray}")
    assert not problems, "prediction names not on the grid:\n  " + "\n  ".join(problems)


if __name__ == "__main__":
    tests = [v for k, v in sorted(globals().items()) if k.startswith("test_")]
    failed = 0
    for t in tests:
        try:
            t()
            print(f"PASS  {t.__name__}")
        except AssertionError as exc:
            failed += 1
            print(f"FAIL  {t.__name__}\n      {exc}")
        except Exception as exc:
            failed += 1
            print(f"ERROR {t.__name__}: {type(exc).__name__}: {exc}")
    print(f"\n{len(tests) - failed}/{len(tests)} passed")
    sys.exit(1 if failed else 0)